  data_entities: { kind: 'longtext', q: { ar: 'ما المعلومات التي يجب أن يحفظها النظام؟', en: 'What information must the system keep?' }, help: { ar: 'مثال: عملاء، طلبات، فواتير.', en: 'Example: customers, orders, invoices.' } },
